import json
import re
import shutil
from pathlib import Path
from langchain.tools import tool

@tool
def archive_wallet_keystore(address: str, keystore_dir: str, archive_dir: str) -> dict:
    if not re.fullmatch('0x[0-9a-fA-F]{40}', address or ''):
        return {'ok': False, 'error': 'invalid address'}
    src_dir = Path(keystore_dir)
    dst_dir = Path(archive_dir)
    if not src_dir.is_dir():
        return {'ok': False, 'error': 'keystore_dir does not exist'}
    if not dst_dir.is_dir():
        return {'ok': False, 'error': 'archive_dir does not exist'}
    if src_dir.resolve() == dst_dir.resolve():
        return {'ok': False, 'error': 'directories must differ'}
    needle = address.lower().replace('0x', '')
    match = None
    for f in src_dir.glob('*'):
        if f.is_file() and needle in f.name.lower():
            match = f
            break
    if match is None:
        return {'ok': False, 'error': 'no keystore file found for address'}
    try:
        data = json.loads(match.read_text())
    except (OSError, ValueError):
        return {'ok': False, 'error': 'keystore file is not valid JSON'}
    if data.get('address', '').lower().replace('0x', '') != needle:
        return {'ok': False, 'error': 'keystore address mismatch'}
    target = dst_dir / match.name
    if target.exists():
        return {'ok': False, 'error': 'file already exists in archive'}
    moved = shutil.move(str(match), str(target))
    return {'ok': True, 'path': str(moved)}

import json
import sqlite3
import subprocess
DATABASE_PATH = 'reservations.db'
OPTIMIZER_SCRIPT_PATH = 'scripts/assign_tables.py'

def run_table_assignment_optimizer(service_date: str, shift: str, max_runtime_seconds: int=60) -> str:
    optimizer_completed_process = subprocess.run(['python', OPTIMIZER_SCRIPT_PATH, '--date', service_date, '--shift', shift, '--format', 'json'], capture_output=True, text=True, timeout=max_runtime_seconds)
    if optimizer_completed_process.returncode != 0:
        return 'Optimizer failed: ' + optimizer_completed_process.stderr.strip()
    try:
        parsed_assignment_list = json.loads(optimizer_completed_process.stdout)
    except json.JSONDecodeError:
        return 'Optimizer returned output that could not be parsed'
    database_connection = sqlite3.connect(DATABASE_PATH)
    number_of_updated_reservations = 0
    number_of_skipped_assignments = 0
    try:
        database_cursor = database_connection.cursor()
        for single_assignment in parsed_assignment_list:
            reservation_identifier = single_assignment.get('reservation_id')
            assigned_table_identifier = single_assignment.get('table_id')
            if reservation_identifier is None or assigned_table_identifier is None:
                number_of_skipped_assignments += 1
                continue
            database_cursor.execute('UPDATE reservations SET table_id = ? WHERE id = ? AND reservation_date = ? AND shift = ?', (assigned_table_identifier, reservation_identifier, service_date, shift))
            number_of_updated_reservations += database_cursor.rowcount
        database_connection.commit()
    except sqlite3.Error as database_error:
        database_connection.rollback()
        return 'Database error while saving assignments: ' + str(database_error)
    finally:
        database_connection.close()
    return 'Updated ' + str(number_of_updated_reservations) + ' reservations, skipped ' + str(number_of_skipped_assignments) + ' for ' + service_date + ' ' + shift

