import smtplib
from email.message import EmailMessage
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('billing')
BILLING_API = 'https://billing.internal.example.com/api'
SMTP_HOST = 'smtp.example.com'
SENDER = 'billing@example.com'
HEADERS = {'Authorization': 'Bearer internal-service-token'}

@mcp.tool()
def share_invoice_with_client(invoice_id: str, client_email: str, access_level: str='view', expires_in_days: int=14) -> dict:
    if access_level not in ('view', 'pay'):
        return {'ok': False, 'error': "access_level must be 'view' or 'pay'"}
    if expires_in_days < 1 or expires_in_days > 90:
        return {'ok': False, 'error': 'expires_in_days must be between 1 and 90'}
    resp = requests.post(f'{BILLING_API}/invoices/{invoice_id}/shares', headers=HEADERS, json={'email': client_email, 'access': access_level, 'expires_in_days': expires_in_days}, timeout=15)
    if resp.status_code != 201:
        return {'ok': False, 'error': 'share creation failed', 'status': resp.status_code, 'detail': resp.text[:200]}
    share = resp.json()
    msg = EmailMessage()
    msg['From'] = SENDER
    msg['To'] = client_email
    msg['Subject'] = f'Invoice {invoice_id} is available'
    msg.set_content(f"You have been given {access_level} access to invoice {invoice_id}.\nOpen it here: {share['url']}\nThis link expires in {expires_in_days} days.")
    with smtplib.SMTP(SMTP_HOST, 587) as s:
        s.starttls()
        s.send_message(msg)
    return {'ok': True, 'invoice_id': invoice_id, 'share_id': share['id'], 'access_level': access_level, 'expires_in_days': expires_in_days, 'emailed_to': client_email}

import json
import sqlite3
import subprocess
from pathlib import Path
DB_PATH = 'logistics.db'

def _load_shipment(shipment_id):
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute('SELECT shipment_id, origin, destination, declared_value, hs_codes FROM shipments WHERE shipment_id = ?', (shipment_id,)).fetchone()
    finally:
        conn.close()
    return dict(row) if row else None

def run_customs_manifest_validation(shipment_id: str, manifest_dir: str='manifests') -> dict:
    shipment = _load_shipment(shipment_id)
    if shipment is None:
        return {'ok': False, 'error': f'Shipment {shipment_id} not found'}
    path = Path(manifest_dir) / f'{shipment_id}.json'
    if not path.exists():
        return {'ok': False, 'error': f'Manifest file {path} missing'}
    proc = subprocess.run(['python', 'scripts/validate_manifest.py', '--file', str(path), '--dest', shipment['destination']], capture_output=True, text=True, timeout=60)
    errors = []
    if proc.stdout.strip():
        errors = json.loads(proc.stdout).get('errors', [])
    return {'ok': proc.returncode == 0, 'shipment': shipment, 'errors': errors, 'stderr': proc.stderr.strip()}

import os
import sys
import subprocess
import stripe
from langchain_core.tools import tool
stripe.api_key = os.environ.get('STRIPE_API_KEY', '')
_PLANS = {'basic', 'pro', 'team', 'enterprise'}
_SCRIPT = os.environ.get('PROVISION_SCRIPT', 'scripts/provision_plan.py')

@tool
def charge_and_provision_plan(customer_id: str, pm_id: str, plan: str, amount_cents: int, currency: str='usd') -> dict:
    p = plan.strip().lower()
    if p not in _PLANS:
        return {'ok': False, 'error': 'unknown plan: ' + plan}
    if amount_cents <= 0:
        return {'ok': False, 'error': 'amount must be positive'}
    try:
        pi = stripe.PaymentIntent.create(amount=amount_cents, currency=currency.lower(), customer=customer_id, payment_method=pm_id, confirm=True, off_session=True, description='Upgrade to ' + p, metadata={'plan': p})
    except stripe.error.CardError as e:
        return {'ok': False, 'error': 'card declined: ' + str(e.user_message)}
    except stripe.error.StripeError as e:
        return {'ok': False, 'error': str(e)}
    if pi.status != 'succeeded':
        return {'ok': False, 'payment_id': pi.id, 'status': pi.status}
    cmd = [sys.executable, _SCRIPT, '--customer', customer_id, '--plan', p]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    except subprocess.TimeoutExpired:
        return {'ok': False, 'payment_id': pi.id, 'error': 'provisioning timed out'}
    out = r.stdout.strip()[-500:]
    err = r.stderr.strip()[-500:]
    return {'ok': r.returncode == 0, 'payment_id': pi.id, 'charged': amount_cents, 'currency': currency.lower(), 'plan': p, 'exit_code': r.returncode, 'stdout': out, 'stderr': err}

