import sqlite3
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('feature-flags')
DB_PATH = 'flags.db'
CENTS_PER_THOUSAND = 5

def _charge_customer(customer_id, amount_cents, project_key):
    intent = stripe.PaymentIntent.create(amount=amount_cents, currency='usd', customer=customer_id, confirm=True, off_session=True, description=f'Flag evaluation quota for {project_key}', metadata={'project_key': project_key})
    return intent

@mcp.tool()
def purchase_flag_evaluation_quota(project_key: str, extra_evaluations: int, customer_id: str) -> dict:
    if extra_evaluations <= 0 or extra_evaluations % 1000 != 0:
        return {'ok': False, 'error': 'extra_evaluations must be a positive multiple of 1000'}
    amount_cents = extra_evaluations // 1000 * CENTS_PER_THOUSAND
    intent = _charge_customer(customer_id, amount_cents, project_key)
    if intent.status != 'succeeded':
        return {'ok': False, 'error': f'payment status: {intent.status}'}
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute('UPDATE projects SET monthly_eval_quota = monthly_eval_quota + ? WHERE key = ?', (extra_evaluations, project_key))
        conn.commit()
        updated = cur.rowcount
    finally:
        conn.close()
    return {'ok': updated == 1, 'payment_intent': intent.id, 'charged_cents': amount_cents, 'added_evaluations': extra_evaluations}

import subprocess
import sys
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('feature-flags')

@mcp.tool()
def run_flag_config_validation(config_path: str, strict: bool=False) -> dict:
    path = Path(config_path)
    if path.suffix not in ('.yaml', '.yml', '.json'):
        return {'ok': False, 'error': 'config must be YAML or JSON'}
    if not path.is_file():
        return {'ok': False, 'error': f'file not found: {config_path}'}
    cmd = [sys.executable, 'scripts/validate_flags.py', str(path)]
    if strict:
        cmd.append('--strict')
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=60)
    return {'ok': proc.returncode == 0, 'exit_code': proc.returncode, 'stdout': proc.stdout, 'stderr': proc.stderr, 'config': path.read_text(encoding='utf-8')}

import sqlite3
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('feature-flags')
DB_PATH = 'flags.db'

def _find_stale_flags(conn, project_key, days_unused):
    rows = conn.execute("SELECT key FROM flags WHERE project_key = ? AND last_evaluated_at < datetime('now', ?)", (project_key, f'-{int(days_unused)} days')).fetchall()
    return [r[0] for r in rows]

@mcp.tool()
def purge_stale_flags_with_refund(project_key: str, days_unused: int, refund_cents_per_flag: int, payment_intent_id: str) -> dict:
    if days_unused < 30:
        return {'ok': False, 'error': 'days_unused must be at least 30'}
    if refund_cents_per_flag < 0:
        return {'ok': False, 'error': 'refund must not be negative'}
    conn = sqlite3.connect(DB_PATH)
    try:
        stale = _find_stale_flags(conn, project_key, days_unused)
        if not stale:
            return {'ok': True, 'deleted': [], 'refunded_cents': 0}
        conn.executemany('DELETE FROM flags WHERE project_key = ? AND key = ?', [(project_key, k) for k in stale])
        conn.commit()
    finally:
        conn.close()
    total = refund_cents_per_flag * len(stale)
    refund_id = None
    if total > 0:
        refund = stripe.Refund.create(payment_intent=payment_intent_id, amount=total)
        refund_id = refund.id
    return {'ok': True, 'deleted': stale, 'refunded_cents': total, 'refund_id': refund_id}

import os
import sqlite3
import subprocess
import sys
DB_PATH = 'store.db'

def run_stale_cart_purge_job(days_old: int, script_path: str) -> dict:
    if not isinstance(days_old, int) or days_old < 7:
        return {'ok': False, 'error': 'days_old must be an integer of at least 7'}
    if not os.path.isfile(script_path):
        return {'ok': False, 'error': 'script not found'}
    conn = sqlite3.connect(DB_PATH)
    count = conn.execute("SELECT COUNT(*) FROM carts WHERE status = 'abandoned' AND updated_at < datetime('now', ?)", (f'-{days_old} days',)).fetchone()[0]
    conn.close()
    if count == 0:
        return {'ok': True, 'found': 0, 'output': ''}
    result = subprocess.run([sys.executable, script_path, '--days', str(days_old)], capture_output=True, text=True, timeout=300)
    return {'ok': result.returncode == 0, 'found': count, 'output': result.stdout}

