from dataclasses import dataclass
import stripe
from agents import function_tool
DB_PATH = 'ticketing.db'

@dataclass
class CheckoutResult:
    order_id: str
    payment_intent_id: str
    status: str
    fulfillment_job_id: str

@function_tool
def charge_and_run_ticket_checkout(order_id: str, payment_method_id: str) -> CheckoutResult:
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute("SELECT total_cents, currency, customer_id FROM orders WHERE id = ? AND status = 'held'", (order_id,)).fetchone()
    if row is None:
        conn.close()
        return CheckoutResult(order_id, '', 'order_not_found_or_not_held', '')
    total_cents, currency, customer_id = row
    intent = stripe.PaymentIntent.create(amount=total_cents, currency=currency, customer=customer_id, payment_method=payment_method_id, confirm=True, off_session=True, idempotency_key=f'checkout-{order_id}')
    job = stripe_fulfillment_queue.run_job('issue_tickets', order_id=order_id)
    conn.close()
    return CheckoutResult(order_id, intent.id, intent.status, job.id)

import boto3
from langchain_core.tools import tool
_s3 = boto3.client('s3')

@tool
def move_objects_by_extension(bucket: str, src_prefix: str, dst_prefix: str, ext: str, dry_run: bool=True) -> dict:
    if not src_prefix.endswith('/'):
        src_prefix += '/'
    if not dst_prefix.endswith('/'):
        dst_prefix += '/'
    if not ext.startswith('.'):
        ext = '.' + ext
    pg = _s3.get_paginator('list_objects_v2')
    hits = []
    for page in pg.paginate(Bucket=bucket, Prefix=src_prefix):
        for o in page.get('Contents', []):
            k = o['Key']
            if k.lower().endswith(ext.lower()):
                hits.append(k)
    moved = []
    failed = []
    if dry_run:
        return {'dry_run': True, 'matches': hits, 'moved': moved, 'failed': failed}
    for k in hits:
        nk = dst_prefix + k[len(src_prefix):]
        if nk == k:
            continue
        try:
            _s3.copy_object(Bucket=bucket, Key=nk, CopySource={'Bucket': bucket, 'Key': k})
            _s3.delete_object(Bucket=bucket, Key=k)
            moved.append(nk)
        except Exception as e:
            failed.append({'key': k, 'error': str(e)})
    return {'dry_run': False, 'matches': hits, 'moved': moved, 'failed': failed}

import sqlite3
DB_PATH = 'travel.db'

def transfer_booking_to_traveler(booking_id: str, from_traveler_id: str, to_traveler_id: str) -> dict:
    if not booking_id or not booking_id.strip():
        return {'ok': False, 'error': 'booking_id is required'}
    if not from_traveler_id or not to_traveler_id:
        return {'ok': False, 'error': 'both traveler IDs are required'}
    if from_traveler_id == to_traveler_id:
        return {'ok': False, 'error': 'source and destination travelers are the same'}
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.cursor()
        cur.execute('SELECT 1 FROM travelers WHERE id = ?', (to_traveler_id,))
        if cur.fetchone() is None:
            return {'ok': False, 'error': 'destination traveler not found'}
        cur.execute('SELECT trip_id FROM bookings WHERE id = ? AND owner_id = ?', (booking_id, from_traveler_id))
        row = cur.fetchone()
        if row is None:
            return {'ok': False, 'error': 'booking not found for source traveler'}
        cur.execute('SELECT id FROM trips WHERE traveler_id = ? AND is_default = 1', (to_traveler_id,))
        trip = cur.fetchone()
        if trip is None:
            return {'ok': False, 'error': 'destination has no default trip'}
        cur.execute('UPDATE bookings SET trip_id = ?, owner_id = ? WHERE id = ?', (trip[0], to_traveler_id, booking_id))
        cur.execute('DELETE FROM booking_access WHERE booking_id = ? AND traveler_id = ?', (booking_id, from_traveler_id))
        cur.execute("INSERT INTO booking_access (booking_id, traveler_id, role) VALUES (?, ?, 'owner')", (booking_id, to_traveler_id))
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'booking_id': booking_id, 'new_owner': to_traveler_id, 'trip_id': trip[0]}

