        cur = conn.cursor()
        cur.execute('SELECT 1 FROM travelers WHERE id = ?', (to_traveler_id,))
        if cur.fetchone() is None:
            return {'ok': False, 'error': 'destination traveler not found'}
        cur.execute('SELECT trip_id FROM bookings WHERE id = ? AND owner_id = ?', (booking_id, from_traveler_id))
        row = cur.fetchone()
        if row is None:
            return {'ok': False, 'error': 'booking not found for source traveler'}
        cur.execute('SELECT id FROM trips WHERE traveler_id = ? AND is_default = 1', (to_traveler_id,))
        trip = cur.fetchone()
        if trip is None:
            return {'ok': False, 'error': 'destination has no default trip'}
        cur.execute('UPDATE bookings SET trip_id = ?, owner_id = ? WHERE id = ?', (trip[0], to_traveler_id, booking_id))
        cur.execute('DELETE FROM booking_access WHERE booking_id = ? AND traveler_id = ?', (booking_id, from_traveler_id))
        cur.execute("INSERT INTO booking_access (booking_id, traveler_id, role) VALUES (?, ?, 'owner')", (booking_id, to_traveler_id))
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'booking_id': booking_id, 'new_owner': to_traveler_id, 'trip_id': trip[0]}

