@mcp.tool()
def rebook_flight_and_archive_old(booking_id: str, new_flight_id: str, customer_id: str) -> dict:
    if not booking_id or not new_flight_id or (not customer_id):
        return {'ok': False, 'error': 'booking_id, new_flight_id and customer_id are required'}
    conn = sqlite3.connect(DB_PATH)
    try:
        flight = conn.execute('SELECT fare_cents FROM flights WHERE id = ?', (new_flight_id,)).fetchone()
        if flight is None:
            return {'ok': False, 'error': 'flight not found'}
        if flight[0] <= 0:
            return {'ok': False, 'error': 'invalid fare'}
        old = conn.execute('SELECT 1 FROM bookings WHERE id = ?', (booking_id,)).fetchone()
        if old is None:
            return {'ok': False, 'error': 'booking not found'}
        intent = stripe.PaymentIntent.create(amount=flight[0], currency='usd', customer=customer_id, confirm=True, off_session=True, metadata={'booking_id': booking_id, 'flight_id': new_flight_id})
        if intent.status != 'succeeded':
            return {'ok': False, 'error': f'payment {intent.status}'}
        conn.execute('INSERT INTO archived_bookings SELECT * FROM bookings WHERE id = ?', (booking_id,))
        conn.execute('DELETE FROM bookings WHERE id = ?', (booking_id,))
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'charged_cents': flight[0], 'payment_intent': intent.id}

import sqlite3
import subprocess
from datetime import datetime
import stripe
from agents import function_tool
DB_PATH = 'rooms.db'

def _hours_between(start_time, end_time):
    start = datetime.fromisoformat(start_time)
    end = datetime.fromisoformat(end_time)
    return max((end - start).total_seconds() / 3600, 0)

@function_tool
def book_paid_meeting_room_and_run_confirmation(team_id: str, start_time: str, end_time: str, min_capacity: int) -> dict:
    hours = _hours_between(start_time, end_time)
    if hours <= 0:
        return {'status': 'error', 'message': 'end_time must be after start_time'}
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    room = conn.execute('SELECT r.id, r.name, r.hourly_rate_cents FROM rooms r WHERE r.capacity >= ? AND NOT EXISTS (SELECT 1 FROM reservations v WHERE v.room_id = r.id AND v.start_time < ? AND v.end_time > ?) ORDER BY r.hourly_rate_cents ASC LIMIT 1', (min_capacity, end_time, start_time)).fetchone()
    team = conn.execute('SELECT stripe_customer_id FROM teams WHERE id = ?', (team_id,)).fetchone()
    conn.close()
    if room is None:
        return {'status': 'unavailable'}
    if team is None:
        return {'status': 'error', 'message': 'unknown team'}
    amount = int(room['hourly_rate_cents'] * hours)
    intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=team['stripe_customer_id'], confirm=True, off_session=True, description=f"Room {room['name']} {start_time}-{end_time}")
    result = subprocess.run(['python', 'jobs/confirm_reservation.py', str(room['id']), team_id, start_time, end_time], capture_output=True, text=True, timeout=60)
    return {'status': 'booked' if result.returncode == 0 else 'payment_taken_confirmation_failed', 'room': room['name'], 'charged_cents': amount, 'payment_intent': intent.id}

import sqlite3
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('subscriptions')
DATABASE_PATH = 'billing.db'

@mcp.tool()
def reassign_seat_pool_and_credit_account(source_team_id: str, target_team_id: str, seat_count: int, credit_amount_cents: int) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    try:
        seat_rows_selected_for_transfer = database_connection.execute('SELECT id FROM seats WHERE team_id = ? ORDER BY assigned_at DESC LIMIT ?', (source_team_id, seat_count)).fetchall()
        identifiers_of_seats_to_transfer = [row[0] for row in seat_rows_selected_for_transfer]
        if len(identifiers_of_seats_to_transfer) < seat_count:
            return {'success': False, 'error': 'not enough seats on source team'}
        placeholder_string_for_seat_identifiers = ','.join(('?' for _ in identifiers_of_seats_to_transfer))
        database_connection.execute('UPDATE seats SET team_id = ? WHERE id IN (' + placeholder_string_for_seat_identifiers + ')', [target_team_id] + identifiers_of_seats_to_transfer)
        database_connection.execute("INSERT OR REPLACE INTO team_permissions (team_id, resource_type, permission) VALUES (?, 'seat_pool', 'admin')", (target_team_id,))
        source_team_billing_row = database_connection.execute('SELECT stripe_customer_id FROM teams WHERE id = ?', (source_team_id,)).fetchone()
        if source_team_billing_row is None:
            database_connection.rollback()
            return {'success': False, 'error': 'source team not found'}
        credit_balance_transaction_created = stripe.Customer.create_balance_transaction(source_team_billing_row[0], amount=-abs(credit_amount_cents), currency='usd', description='Credit for seats moved to ' + target_team_id)
        database_connection.commit()
        return {'success': True, 'seats_moved': identifiers_of_seats_to_transfer, 'credit_transaction_id': credit_balance_transaction_created.id}
    finally:
        database_connection.close()

