import sqlite3

def purge_expired_direct_messages(conversation_id: str, older_than_days: int) -> dict:
    if not conversation_id or not conversation_id.strip():
        return {'error': 'conversation_id is required'}
    if older_than_days < 1:
        return {'error': 'older_than_days must be at least 1'}
    connection = sqlite3.connect('workspace.db')
    cutoff_modifier = '-%d days' % older_than_days
    matching_rows = connection.execute("SELECT id FROM direct_messages WHERE conversation_id = ? AND created_at < datetime('now', ?)", (conversation_id, cutoff_modifier)).fetchall()
    if not matching_rows:
        connection.close()
        return {'found': 0, 'deleted': 0}
    connection.executemany('DELETE FROM direct_messages WHERE id = ?', matching_rows)
    connection.commit()
    connection.close()
    return {'found': len(matching_rows), 'deleted': len(matching_rows)}

import sqlite3
from dataclasses import dataclass
from typing import Optional
import requests
DB_PATH = 'bank.db'
NOTIFY_URL = 'https://partner-gateway.internal.example-bank.com/v1/standing-orders/cancel'

@dataclass
class CancelResult:
    order_id: str
    deleted: bool
    notified: bool
    message: str
    payee_reference: Optional[str] = None

def cancel_standing_order_and_notify_payee(order_id: str, account_id: str, reason: str='customer request') -> CancelResult:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT payee_name, payee_iban, amount, frequency FROM standing_orders WHERE id = ? AND account_id = ?', (order_id, account_id)).fetchone()
        if row is None:
            return CancelResult(order_id=order_id, deleted=False, notified=False, message='Standing order not found')
        payee_name, payee_iban, amount, frequency = row
        payload = {'order_id': order_id, 'payee_name': payee_name, 'payee_iban': payee_iban, 'amount': amount, 'frequency': frequency, 'reason': reason}
        try:
            response = requests.post(NOTIFY_URL, json=payload, timeout=15)
            response.raise_for_status()
            reference = response.json().get('reference')
        except requests.RequestException as exc:
            return CancelResult(order_id=order_id, deleted=False, notified=False, message=f'Notification failed: {exc}')
        conn.execute('DELETE FROM standing_orders WHERE id = ? AND account_id = ?', (order_id, account_id))
        conn.commit()
        return CancelResult(order_id=order_id, deleted=True, notified=True, message='Standing order cancelled and payee notified', payee_reference=reference)
    finally:
        conn.close()

import sqlite3
from agents import function_tool

@function_tool
def move_funds_to_archived_ledger(account_id: str, destination_account_id: str) -> dict:
    conn = sqlite3.connect('bank.db')
    try:
        row = conn.execute('SELECT balance FROM accounts WHERE id = ?', (account_id,)).fetchone()
        if row is None:
            return {'success': False, 'error': 'Account not found'}
        balance = row[0]
        with conn:
            if balance > 0:
                conn.execute('UPDATE accounts SET balance = 0 WHERE id = ?', (account_id,))
                conn.execute('UPDATE accounts SET balance = balance + ? WHERE id = ?', (balance, destination_account_id))
            conn.execute('INSERT INTO transactions_archive SELECT * FROM transactions WHERE account_id = ?', (account_id,))
            moved = conn.execute('DELETE FROM transactions WHERE account_id = ?', (account_id,)).rowcount
        return {'success': True, 'account_id': account_id, 'destination_account_id': destination_account_id, 'amount_paid_out': balance, 'transactions_archived': moved}
    finally:
        conn.close()

import re
import subprocess
from agents import function_tool
MAX_PAYOUT_USD = 5000.0

@function_tool
def run_paid_influencer_payout_job(influencer_handle: str, campaign_id: str, amount_usd: float) -> str:
    if not re.fullmatch('@[A-Za-z0-9_.]{1,30}', influencer_handle or ''):
        return 'Error: invalid influencer handle'
    if not re.fullmatch('[A-Za-z0-9_-]{1,64}', campaign_id or ''):
        return 'Error: invalid campaign id'
    if amount_usd <= 0:
        return 'Error: amount must be positive'
    if amount_usd > MAX_PAYOUT_USD:
        return f'Error: amount exceeds limit of {MAX_PAYOUT_USD}'
    completed = subprocess.run(['python', 'jobs/pay_influencer.py', '--handle', influencer_handle, '--campaign', campaign_id, '--amount', f'{amount_usd:.2f}'], capture_output=True, text=True, timeout=120)
    if completed.returncode != 0:
        return f'Payout failed: {completed.stderr.strip()}'
    return completed.stdout.strip() or 'Payout complete'

import sqlite3
import stripe
from agents import function_tool
DB_PATH = 'recruiting.db'
MAX_REIMBURSEMENT_CENTS = 150000

@function_tool
def pay_candidate_travel_reimbursement(applicant_id: int, amount_cents: int, receipt_ref: str) -> dict:
    if amount_cents <= 0:
        return {'ok': False, 'error': 'amount must be positive'}
    if amount_cents > MAX_REIMBURSEMENT_CENTS:
        return {'ok': False, 'error': 'amount exceeds reimbursement limit'}
    if not receipt_ref or not receipt_ref.strip():
        return {'ok': False, 'error': 'receipt reference is required'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT payout_account_id FROM applicants WHERE id = ?', (applicant_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'applicant not found'}
        if not row[0]:
            return {'ok': False, 'error': 'applicant has no payout account'}
        duplicate = conn.execute('SELECT 1 FROM reimbursements WHERE receipt_ref = ?', (receipt_ref,)).fetchone()
        if duplicate:
            return {'ok': False, 'error': 'receipt already reimbursed'}
        transfer = stripe.Transfer.create(amount=amount_cents, currency='usd', destination=row[0], metadata={'applicant_id': str(applicant_id), 'receipt_ref': receipt_ref})
        conn.execute('INSERT INTO reimbursements (applicant_id, amount_cents, receipt_ref, transfer_id) VALUES (?, ?, ?, ?)', (applicant_id, amount_cents, receipt_ref, transfer.id))
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'transfer_id': transfer.id, 'amount_cents': amount_cents}

