import subprocess
from contextlib import contextmanager
from pathlib import Path
from agents import tool

@contextmanager
def _log_file(name: str):
    path = Path.home() / '.photo_backup_logs'
    path.mkdir(exist_ok=True)
    fh = open(path / f'{name}.log', 'w', encoding='utf-8')
    try:
        yield fh
    finally:
        fh.close()

@tool
def run_album_backup_sync(album_dir: str, remote: str) -> dict:
    source = Path(album_dir)
    if not source.is_dir():
        return {'ok': False, 'error': 'album folder not found'}
    with _log_file(source.name) as log:
        proc = subprocess.run(['rclone', 'copy', str(source), remote, '--stats-one-line', '-v'], stdout=log, stderr=subprocess.STDOUT, text=True)
    return {'ok': proc.returncode == 0, 'exit_code': proc.returncode, 'log': source.name + '.log'}

import shutil
from pathlib import Path
from kubernetes import client, config
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('k8s-ops')

def _api():
    try:
        config.load_incluster_config()
    except config.ConfigException:
        config.load_kube_config()
    return client.AppsV1Api()

@mcp.tool()
def sweep_orphaned_manifests(namespace: str, manifests_dir: str, orphan_dir: str, dry_run: bool=False) -> dict:
    a = _api()
    r = a.list_namespaced_deployment(namespace)
    live = {d.metadata.name for d in r.items}
    src = Path(manifests_dir)
    dst = Path(orphan_dir)
    if not src.is_dir():
        return {'error': f'{manifests_dir} is not a directory'}
    mv = []
    kept = []
    skipped = []
    for f in sorted(src.iterdir()):
        if not f.is_file() or f.suffix not in ('.yaml', '.yml'):
            continue
        n = f.stem
        if n in live:
            kept.append(f.name)
            continue
        t = dst / f.name
        if t.exists():
            skipped.append(f.name)
            continue
        mv.append((f, t))
    if not dry_run and mv:
        dst.mkdir(parents=True, exist_ok=True)
        for s, t in mv:
            shutil.move(str(s), str(t))
    return {'namespace': namespace, 'live_deployments': len(live), 'moved': [s.name for s, _ in mv], 'kept': kept, 'skipped_name_clash': skipped, 'dry_run': dry_run}

