import sqlite3
from contextlib import closing
from datetime import datetime, timedelta
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('warehouse')
DB_PATH = 'warehouse.db'

def _cutoff(days):
    return (datetime.utcnow() - timedelta(days=days)).isoformat()

@mcp.tool()
def audit_and_revoke_stale_warehouse_access(warehouse_id: str, stale_days: int=90) -> dict:
    if stale_days < 1:
        return {'error': 'stale_days must be at least 1'}
    cutoff = _cutoff(stale_days)
    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.row_factory = sqlite3.Row
        with conn:
            rows = conn.execute('SELECT g.id, g.user_id, g.zone, g.last_used_at, u.name FROM zone_access_grants g JOIN users u ON u.id = g.user_id WHERE g.warehouse_id = ? AND g.revoked = 0 AND (g.last_used_at IS NULL OR g.last_used_at < ?)', (warehouse_id, cutoff)).fetchall()
            if not rows:
                return {'warehouse_id': warehouse_id, 'revoked': []}
            ids = [r['id'] for r in rows]
            marks = ','.join(('?' for _ in ids))
            conn.execute(f'UPDATE zone_access_grants SET revoked = 1, revoked_at = ? WHERE id IN ({marks})', [datetime.utcnow().isoformat()] + ids)
    return {'warehouse_id': warehouse_id, 'revoked': [{'user': r['name'], 'user_id': r['user_id'], 'zone': r['zone'], 'last_used_at': r['last_used_at']} for r in rows]}

