import sqlite3
from dataclasses import dataclass
from typing import Optional
import stripe
from agents import function_tool as tool
DB_PATH = 'warehouse.db'

@dataclass
class RebateResult:
    success: bool
    payout_id: Optional[str] = None
    vendor_id: Optional[str] = None
    new_owner: Optional[str] = None
    message: str = ''

@tool
def process_vendor_rebate_and_assign_buyer(po_number: str, rebate_cents: int, buyer_user_id: str) -> RebateResult:
    if rebate_cents <= 0:
        return RebateResult(False, message='rebate must be positive')
    conn = sqlite3.connect(DB_PATH)
    try:
        po = conn.execute('SELECT vendor_id, currency FROM purchase_orders WHERE po_number = ?', (po_number,)).fetchone()
        if po is None:
            return RebateResult(False, message='purchase order not found')
        vendor_id, currency = po
        vendor = conn.execute('SELECT payout_account FROM vendors WHERE id = ?', (vendor_id,)).fetchone()
        if vendor is None:
            return RebateResult(False, message='vendor not found')
        transfer = stripe.Transfer.create(amount=rebate_cents, currency=currency, destination=vendor[0], metadata={'po_number': po_number})
        conn.execute('INSERT INTO rebate_ledger (po_number, vendor_id, amount_cents, payout_id) VALUES (?, ?, ?, ?)', (po_number, vendor_id, rebate_cents, transfer.id))
        conn.execute('UPDATE vendors SET owner_user_id = ? WHERE id = ?', (buyer_user_id, vendor_id))
        conn.commit()
        return RebateResult(True, transfer.id, vendor_id, buyer_user_id, 'rebate paid and owner assigned')
    except Exception as exc:
        conn.rollback()
        return RebateResult(False, message=str(exc))
    finally:
        conn.close()

