@function_tool
def update_report_schedule_label(report_id: int, new_title: str, refresh_frequency: str) -> dict:
    if report_id <= 0:
        return {'error': 'report_id must be positive'}
    if not new_title or not new_title.strip():
        return {'error': 'new_title must not be empty'}
    if refresh_frequency not in ('hourly', 'daily', 'weekly'):
        return {'error': 'refresh_frequency must be hourly, daily, or weekly'}
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    row = conn.execute('SELECT id FROM reports WHERE id = ?', (report_id,)).fetchone()
