        conn.close()
        return {'error': 'report not found'}
    conn.execute('UPDATE reports SET title = ?, refresh_frequency = ? WHERE id = ?', (new_title.strip(), refresh_frequency, report_id))
    conn.commit()
    updated = dict(conn.execute('SELECT * FROM reports WHERE id = ?', (report_id,)).fetchone())
    conn.close()
    return updated

