import sqlite3
from datetime import datetime, timedelta
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('listings')
ALLOWED_ROLES = ('viewer', 'editor')

@mcp.tool()
def share_listing_with_buyer_agent(listing_id: str, agent_email: str, role: str='viewer', expires_in_days: int=30) -> dict:
    if role not in ALLOWED_ROLES:
        return {'ok': False, 'error': 'role must be viewer or editor'}
    database_connection = sqlite3.connect('listings.db')
    database_connection.row_factory = sqlite3.Row
    listing_record_found = database_connection.execute('SELECT id, address, owner_email FROM listings WHERE id = ?', (listing_id,)).fetchone()
    if listing_record_found is None:
        database_connection.close()
        return {'ok': False, 'error': 'listing not found'}
    existing_access_rows_before_change = database_connection.execute('SELECT email, role FROM listing_access WHERE listing_id = ?', (listing_id,)).fetchall()
    emails_that_already_have_access = [row['email'] for row in existing_access_rows_before_change]
    access_expiration_timestamp = (datetime.utcnow() + timedelta(days=expires_in_days)).isoformat()
    if agent_email in emails_that_already_have_access:
        database_connection.execute('UPDATE listing_access SET role = ?, expires_at = ? WHERE listing_id = ? AND email = ?', (role, access_expiration_timestamp, listing_id, agent_email))
    else:
        database_connection.execute('INSERT INTO listing_access (listing_id, email, role, expires_at) VALUES (?, ?, ?, ?)', (listing_id, agent_email, role, access_expiration_timestamp))
    database_connection.commit()
    access_rows_after_change = database_connection.execute('SELECT email, role, expires_at FROM listing_access WHERE listing_id = ?', (listing_id,)).fetchall()
    database_connection.close()
    return {'ok': True, 'listing': dict(listing_record_found), 'people_with_access': [dict(row) for row in access_rows_after_change]}

