import shutil
from pathlib import Path
import boto3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('backup-tools')
_s3 = boto3.client('s3')

@mcp.tool()
def ship_archive_to_offsite_bucket(archive_path: str, bucket: str, shipped_dir: str) -> dict:
    if not bucket or not bucket.strip():
        return {'ok': False, 'error': 'bucket is required'}
    if not shipped_dir:
        return {'ok': False, 'error': 'shipped_dir is required'}
    src = Path(archive_path)
    if not src.is_file():
        return {'ok': False, 'error': f'archive not found: {archive_path}'}
    if src.stat().st_size == 0:
        return {'ok': False, 'error': 'archive is empty'}
    dest_dir = Path(shipped_dir)
    dest_dir.mkdir(parents=True, exist_ok=True)
    key = f'archives/{src.name}'
    try:
        _s3.upload_file(str(src), bucket, key)
    except Exception as exc:
        return {'ok': False, 'error': str(exc)}
    final = shutil.move(str(src), str(dest_dir / src.name))
    return {'ok': True, 's3_uri': f's3://{bucket}/{key}', 'local_path': final}

import sqlite3
from datetime import datetime, timezone
from agents import function_tool
_DB_PATH = 'backup_catalog.db'
_LEVELS = {'restore', 'restore_admin'}

@function_tool
def register_backup_and_grant_restore_access(backup_id: str, location: str, size_bytes: int, grantee: str, access_level: str) -> str:
    if not backup_id or not backup_id.strip():
        return 'error: backup_id is required'
    if not location or not location.strip():
        return 'error: location is required'
    if size_bytes < 0:
        return 'error: size_bytes must not be negative'
    if not grantee or not grantee.strip():
        return 'error: grantee is required'
    if access_level not in _LEVELS:
        return f'error: access_level must be one of {sorted(_LEVELS)}'
    now = datetime.now(timezone.utc).isoformat()
    conn = sqlite3.connect(_DB_PATH)
    try:
        user = conn.execute('SELECT 1 FROM users WHERE username = ?', (grantee,)).fetchone()
        if user is None:
            return f'error: unknown user {grantee}'
        conn.execute('INSERT INTO backups (backup_id, location, size_bytes, registered_at) VALUES (?, ?, ?, ?) ON CONFLICT(backup_id) DO UPDATE SET location = excluded.location, size_bytes = excluded.size_bytes', (backup_id, location, size_bytes, now))
        conn.execute('INSERT INTO backup_acl (backup_id, username, access_level, granted_at) VALUES (?, ?, ?, ?) ON CONFLICT(backup_id, username) DO UPDATE SET access_level = excluded.access_level, granted_at = excluded.granted_at', (backup_id, grantee, access_level, now))
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        return f'error: database failure: {exc}'
    finally:
        conn.close()
    return f'registered {backup_id} and granted {access_level} to {grantee}'

import subprocess
from contextlib import contextmanager
from agents import function_tool

@contextmanager
def _restore_lock(target_dir):
    lock = subprocess.Popen(['flock', '-n', f'{target_dir}.lock', 'sleep', '3600'])
    try:
        yield lock
    finally:
        lock.terminate()

@function_tool
def run_restore_as_service_account(backup_file: str, target_dir: str, owner: str) -> str:
    with _restore_lock(target_dir):
        subprocess.run(['/opt/backup/restore.sh', backup_file, target_dir], check=True)
        subprocess.run(['chown', '-R', f'{owner}:{owner}', target_dir], check=True)
    return f'restored {backup_file} into {target_dir} owned by {owner}'

import json
from dataclasses import dataclass
from pathlib import Path
from agents import function_tool

@dataclass
class ScanResult:
    new_lines: int
    warnings: int
    errors: int
    start_offset: int
    end_offset: int
    reset: bool

@function_tool
def scan_new_log_entries(log_path: str, checkpoint_path: str) -> ScanResult:
    log = Path(log_path)
    cp = Path(checkpoint_path)
    offset = 0
    if cp.is_file():
        offset = json.loads(cp.read_text()).get(log_path, 0)
    size = log.stat().st_size
    reset = offset > size
    if reset:
        offset = 0
    warnings = errors = lines = 0
    with log.open('rb') as fh:
        fh.seek(offset)
        for raw in fh:
            lines += 1
            text = raw.decode('utf-8', errors='replace')
            if ' ERROR ' in text or ' CRITICAL ' in text:
                errors += 1
            elif ' WARNING ' in text:
                warnings += 1
        end = fh.tell()
    state = json.loads(cp.read_text()) if cp.is_file() else {}
    state[log_path] = end
    cp.write_text(json.dumps(state))
    return ScanResult(lines, warnings, errors, offset, end, reset)

