import os
from web3 import Web3
_w3 = Web3(Web3.HTTPProvider(os.environ.get('RPC_URL', 'http://localhost:8545')))
_ABI = [{'name': 'allowance', 'type': 'function', 'stateMutability': 'view', 'inputs': [{'name': 'o', 'type': 'address'}, {'name': 's', 'type': 'address'}], 'outputs': [{'name': '', 'type': 'uint256'}]}, {'name': 'transfer', 'type': 'function', 'stateMutability': 'nonpayable', 'inputs': [{'name': 'to', 'type': 'address'}, {'name': 'v', 'type': 'uint256'}], 'outputs': [{'name': '', 'type': 'bool'}]}, {'name': 'approve', 'type': 'function', 'stateMutability': 'nonpayable', 'inputs': [{'name': 's', 'type': 'address'}, {'name': 'v', 'type': 'uint256'}], 'outputs': [{'name': '', 'type': 'bool'}]}]

def pay_and_revoke_token_allowance(owner_address, spender_address, token_address, amount):
    for addr in (owner_address, spender_address, token_address):
        if not Web3.is_address(addr):
            return {'error': 'invalid address: ' + str(addr)}
    if amount <= 0:
        return {'error': 'amount must be positive'}
    owner = Web3.to_checksum_address(owner_address)
    spender = Web3.to_checksum_address(spender_address)
    token = _w3.eth.contract(address=Web3.to_checksum_address(token_address), abi=_ABI)
    allowance = token.functions.allowance(owner, spender).call()
    if allowance == 0:
        return {'error': 'spender has no allowance'}
    pay_hash = token.functions.transfer(spender, amount).transact({'from': owner})
    revoke_hash = token.functions.approve(spender, 0).transact({'from': owner})
    return {'previous_allowance': allowance, 'payment_tx': pay_hash.hex(), 'revoke_tx': revoke_hash.hex()}

import os
import requests
from agents import function_tool
_API = os.environ.get('WALLET_API_URL', 'https://wallet-api.internal/v1')
_HEADERS = {'Authorization': 'Bearer ' + os.environ.get('WALLET_API_KEY', '')}

@function_tool
def sweep_wallet_dust_balances(wallet_id: str, destination_address: str, max_usd_value: float) -> dict:
    if not wallet_id:
        return {'error': 'wallet_id is required'}
    if not destination_address.startswith('0x') or len(destination_address) != 42:
        return {'error': 'destination_address is not a valid address'}
    if max_usd_value <= 0 or max_usd_value > 100:
        return {'error': 'max_usd_value must be between 0 and 100'}
    resp = requests.get(_API + '/wallets/' + wallet_id + '/balances', headers=_HEADERS, timeout=20)
    if resp.status_code != 200:
        return {'error': 'balance lookup failed', 'status': resp.status_code}
    balances = resp.json().get('balances', [])
    dust = [b for b in balances if 0 < b['usd_value'] < max_usd_value]
    if not dust:
        return {'swept': [], 'message': 'no dust balances found'}
    swept = []
    failed = []
    for b in dust:
        r = requests.post(_API + '/wallets/' + wallet_id + '/transfers', headers=_HEADERS, json={'token': b['token'], 'amount': b['amount'], 'to': destination_address}, timeout=30)
        if r.status_code in (200, 201):
            swept.append({'token': b['token'], 'amount': b['amount'], 'tx': r.json().get('tx_hash')})
        else:
            failed.append(b['token'])
    return {'swept': swept, 'failed': failed}

