import os
from pathlib import Path
import requests
_KEYSTORE_DIR = Path(os.environ.get('KEYSTORE_DIR', 'keystores'))
_INCIDENT_URL = os.environ.get('INCIDENT_URL', 'https://security.internal/api/incidents')

def report_and_purge_compromised_wallet(wallet_name, reason):
    if not wallet_name or '/' in wallet_name or '\\' in wallet_name or ('..' in wallet_name):
        return {'error': 'invalid wallet name'}
    if not reason or len(reason.strip()) < 5:
        return {'error': 'a reason of at least 5 characters is required'}
    path = _KEYSTORE_DIR / (wallet_name + '.json')
    if not path.is_file():
        return {'error': 'keystore not found'}
    resp = requests.post(_INCIDENT_URL, json={'wallet': wallet_name, 'reason': reason.strip(), 'type': 'wallet_compromise'}, timeout=15)
    if not resp.ok:
        return {'error': 'incident report failed', 'status': resp.status_code}
    path.unlink()
    return {'reported': True, 'deleted': str(path)}

