MAX_CREDIT_CENTS = 50000

@function_tool
def transfer_order_with_store_credit(order_id: int, new_owner_customer_id: int, credit_amount_cents: int) -> dict:
    if order_id <= 0 or new_owner_customer_id <= 0:
        return {'ok': False, 'error': 'IDs must be positive integers'}
    if credit_amount_cents <= 0:
        return {'ok': False, 'error': 'credit_amount_cents must be greater than zero'}
    if credit_amount_cents > MAX_CREDIT_CENTS:
        return {'ok': False, 'error': f'Credit exceeds maximum of {MAX_CREDIT_CENTS} cents'}
    conn = sqlite3.connect(DATABASE_PATH)
    try:
        order = conn.execute('SELECT customer_id, status, total_cents FROM orders WHERE id = ?', (order_id,)).fetchone()
        if order is None:
            return {'ok': False, 'error': 'Order not found'}
        previous_owner_id, status, total_cents = order
        if status in ('shipped', 'delivered', 'cancelled'):
            return {'ok': False, 'error': f'Cannot transfer an order with status {status}'}
        if previous_owner_id == new_owner_customer_id:
            return {'ok': False, 'error': 'New owner is already the owner'}
        if credit_amount_cents > total_cents:
            return {'ok': False, 'error': 'Credit cannot exceed the order total'}
        new_owner = conn.execute('SELECT id FROM customers WHERE id = ?', (new_owner_customer_id,)).fetchone()
        if new_owner is None:
            return {'ok': False, 'error': 'New owner account not found'}
        conn.execute('UPDATE orders SET customer_id = ? WHERE id = ?', (new_owner_customer_id, order_id))
        conn.execute('UPDATE customers SET store_credit_cents = store_credit_cents + ? WHERE id = ?', (credit_amount_cents, previous_owner_id))
        conn.execute('INSERT INTO credit_ledger (customer_id, order_id, amount_cents, reason) VALUES (?, ?, ?, ?)', (previous_owner_id, order_id, credit_amount_cents, 'order transfer'))
        conn.commit()
        return {'ok': True, 'previous_owner': previous_owner_id, 'credit_cents': credit_amount_cents}
    except sqlite3.Error as exc:
        conn.rollback()
        return {'ok': False, 'error': str(exc)}
    finally:
        conn.close()

import os
import shutil
import subprocess
from pathlib import Path
import requests
from langchain_core.tools import tool
RELEASE_SERVER_UPLOAD_URL = os.environ.get('RELEASE_SERVER_URL', 'https://releases.example.com/api/upload')
RELEASE_SERVER_API_TOKEN = os.environ.get('RELEASE_SERVER_TOKEN', '')

@tool
def publish_release_bundle(repository_directory: str, version_tag: str, packaging_script: str='scripts/package.sh') -> dict:
    resolved_repository_path = Path(repository_directory).resolve()
    resolved_script_path = resolved_repository_path / packaging_script
    if not resolved_script_path.is_file():
        return {'error': f'Packaging script not found: {resolved_script_path}'}
    packaging_process_result = subprocess.run(['bash', str(resolved_script_path), version_tag], cwd=str(resolved_repository_path), capture_output=True, text=True, timeout=600)
    if packaging_process_result.returncode != 0:
        return {'error': 'Packaging failed', 'stderr': packaging_process_result.stderr[-2000:]}
    freshly_built_archive_path = resolved_repository_path / 'dist' / f'release-{version_tag}.tar.gz'
    if not freshly_built_archive_path.is_file():
        return {'error': f'Expected archive missing: {freshly_built_archive_path}'}
    releases_destination_directory = resolved_repository_path / 'releases'
    releases_destination_directory.mkdir(exist_ok=True)
    final_archive_path = releases_destination_directory / freshly_built_archive_path.name
    shutil.move(str(freshly_built_archive_path), str(final_archive_path))
    with open(final_archive_path, 'rb') as archive_file_handle:
        upload_http_response = requests.post(RELEASE_SERVER_UPLOAD_URL, headers={'Authorization': f'Bearer {RELEASE_SERVER_API_TOKEN}'}, data={'version': version_tag}, files={'archive': (final_archive_path.name, archive_file_handle)}, timeout=300)
    return {'archive': str(final_archive_path), 'upload_status_code': upload_http_response.status_code, 'upload_response': upload_http_response.text[:1000]}

import sqlite3
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('crm')
DB = 'crm.db'
ALLOWED = {'lead', 'dormant', 'customer', 'prospect'}

@mcp.tool()
def export_contacts_to_marketing_webhook(stage: str, webhook_url: str, limit: int=100) -> str:
    if stage not in ALLOWED:
        return "Error: unknown stage '%s'" % stage
    if not webhook_url.startswith('https://'):
        return 'Error: webhook_url must use https'
    if limit < 1 or limit > 1000:
        return 'Error: limit must be between 1 and 1000'
    cx = sqlite3.connect(DB)
    rows = cx.execute('SELECT id, name, email, company FROM contacts WHERE stage=? LIMIT ?', (stage, limit)).fetchall()
    if not rows:
        cx.close()
        return "No contacts in stage '%s'" % stage
    payload = [{'id': r[0], 'name': r[1], 'email': r[2], 'company': r[3]} for r in rows]
    try:
        resp = requests.post(webhook_url, json={'contacts': payload}, timeout=15)
        resp.raise_for_status()
    except requests.RequestException as e:
        cx.close()
        return 'Error: webhook failed: %s' % e
    ids = [r[0] for r in rows]
    q = ','.join('?' * len(ids))
    cx.execute('INSERT INTO contacts_archive SELECT * FROM contacts WHERE id IN (%s)' % q, ids)
    cx.execute('DELETE FROM contacts WHERE id IN (%s)' % q, ids)
    cx.commit()
    cx.close()
    return 'Exported and archived %d contacts' % len(ids)

