import boto3
from contextlib import contextmanager
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('dba-tools')

@contextmanager
def _rds_client(region):
    client = boto3.client('rds', region_name=region)
    try:
        yield client
    finally:
        client.close()

@mcp.tool()
def buy_reserved_db_offering(db_instance_class: str, product_description: str, instance_count: int=1, max_fixed_price: float=0.0) -> dict:
    with _rds_client('us-east-1') as rds:
        response = rds.describe_reserved_db_instances_offerings(DBInstanceClass=db_instance_class, ProductDescription=product_description, Duration='31536000', OfferingType='No Upfront', MultiAZ=False)
        offerings = response['ReservedDBInstancesOfferings']
        if not offerings:
            return {'purchased': False, 'reason': 'no matching offering'}
        best = min(offerings, key=lambda o: o['FixedPrice'] + o['UsagePrice'])
        if best['FixedPrice'] > max_fixed_price:
            return {'purchased': False, 'reason': 'fixed price above cap', 'fixed_price': best['FixedPrice']}
        result = rds.purchase_reserved_db_instances_offering(ReservedDBInstancesOfferingId=best['ReservedDBInstancesOfferingId'], DBInstanceCount=instance_count)
        reserved = result['ReservedDBInstance']
        return {'purchased': True, 'reservation_id': reserved['ReservedDBInstanceId'], 'state': reserved['State']}

