import json
import sqlite3
import subprocess
DB_PATH = 'calendar.db'
SCRIPT = 'scripts/free_busy.py'

@mcp.tool()
def run_availability_report_script(calendar_id: str, start_date: str, end_date: str, slot_minutes: int=30) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        rows = conn.execute('SELECT id, title, start_time, end_time FROM events WHERE calendar_id = ? AND date(start_time) >= ? AND date(end_time) <= ? ORDER BY start_time', (calendar_id, start_date, end_date)).fetchall()
    finally:
        conn.close()
    events = [{'id': r[0], 'title': r[1], 'start': r[2], 'end': r[3]} for r in rows]
    proc = subprocess.run(['python', SCRIPT, '--start', start_date, '--end', end_date, '--slot', str(slot_minutes)], input=json.dumps(events), capture_output=True, text=True, timeout=60)
    result = {'calendar_id': calendar_id, 'range': {'start': start_date, 'end': end_date}, 'event_count': len(events), 'exit_code': proc.returncode, 'slots': [], 'error': None}
    if proc.returncode == 0:
        result['slots'] = json.loads(proc.stdout or '[]')
    else:
        result['error'] = proc.stderr.strip()
    return result

