import sqlite3
import subprocess
from datetime import datetime, timedelta, timezone
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('subscriptions')
DB_PATH = 'subscriptions.db'
BILLING_CLI = 'billing-cli'

def _revoke_entitlements(subscription_id: str) -> tuple[bool, str]:
    proc = subprocess.run([BILLING_CLI, 'entitlements', 'revoke', '--subscription', subscription_id], capture_output=True, text=True, timeout=60)
    return (proc.returncode == 0, proc.stderr.strip())

@mcp.tool()
def purge_expired_trials(days_expired: int, dry_run: bool=False, limit: int=100) -> dict:
    cutoff = (datetime.now(timezone.utc) - timedelta(days=days_expired)).isoformat()
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute("SELECT id, customer_id, plan_id, trial_ends_at FROM subscriptions WHERE status = 'trial_expired' AND converted = 0 AND trial_ends_at < ? ORDER BY trial_ends_at LIMIT ?", (cutoff, limit)).fetchall()
        matched = [dict(r) for r in rows]
        if dry_run:
            return {'dry_run': True, 'matched': matched, 'deleted': [], 'failed': []}
        deleted = []
        failed = []
        for row in matched:
            ok, err = _revoke_entitlements(row['id'])
            if not ok:
                failed.append({'id': row['id'], 'error': err})
                continue
            conn.execute('DELETE FROM subscriptions WHERE id = ?', (row['id'],))
            deleted.append(row['id'])
        conn.commit()
        return {'dry_run': False, 'matched': matched, 'deleted': deleted, 'failed': failed}
    finally:
        conn.close()

import json
import os
import subprocess
import stripe
stripe.api_key = os.environ.get('STRIPE_API_KEY', '')

def charge_plan_upgrade_proration(customer_id: str, payment_method_id: str, new_plan_id: str, prorated_amount_cents: int, country: str, currency: str='usd') -> dict:
    if prorated_amount_cents <= 0:
        return {'success': False, 'error': 'prorated_amount_cents must be positive'}
    proc = subprocess.run(['tax-calc', '--country', country, '--amount', str(prorated_amount_cents), '--format', 'json'], capture_output=True, text=True, timeout=30)
    if proc.returncode != 0:
        return {'success': False, 'error': f'tax calculation failed: {proc.stderr.strip()}'}
    try:
        tax_cents = int(json.loads(proc.stdout)['tax_cents'])
    except (ValueError, KeyError, TypeError):
        return {'success': False, 'error': 'unparseable tax calculator output'}
    total = prorated_amount_cents + tax_cents
    try:
        intent = stripe.PaymentIntent.create(amount=total, currency=currency, customer=customer_id, payment_method=payment_method_id, off_session=True, confirm=True, description=f'Upgrade proration for plan {new_plan_id}', metadata={'plan_id': new_plan_id, 'tax_cents': str(tax_cents)})
    except stripe.error.CardError as exc:
        return {'success': False, 'error': exc.user_message, 'total_cents': total}
    return {'success': intent.status == 'succeeded', 'payment_intent_id': intent.id, 'status': intent.status, 'subtotal_cents': prorated_amount_cents, 'tax_cents': tax_cents, 'total_cents': total, 'currency': currency}

