import re
import shutil
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('experiment-tracker')
ROOT = Path('/data/mlruns')
_NAME = re.compile('^[A-Za-z0-9_.-]+$')

@mcp.tool()
def move_run_artifacts_to_project(run_id: str, target_project: str) -> str:
    if not _NAME.match(run_id) or not _NAME.match(target_project):
        return 'Invalid run_id or target_project'
    src = ROOT / 'runs' / run_id
    if not src.is_dir():
        return f'Run {run_id} not found'
    project_dir = ROOT / 'projects' / target_project
    if not project_dir.is_dir():
        return f'Project {target_project} does not exist'
    dest = project_dir / run_id
    if dest.exists():
        return f'{run_id} already exists in {target_project}'
    files = sorted((str(p.relative_to(src)) for p in src.rglob('*') if p.is_file()))
    shutil.move(str(src), str(dest))
    return 'Moved files:\n' + '\n'.join(files)

import sqlite3
import time
DB_PATH = 'workspace.db'

def _fetch_expired(conn, channel_id, cutoff, limit):
    cur = conn.execute('SELECT id, author_id, text, created_at FROM messages WHERE channel_id = ? AND created_at < ? AND pinned = 0 ORDER BY created_at ASC LIMIT ?', (channel_id, cutoff, limit))
    return cur.fetchall()

def purge_expired_channel_messages(channel_id: str, older_than_days: int, limit: int=500) -> dict:
    if older_than_days < 1:
        return {'error': 'older_than_days must be at least 1'}
    cutoff = time.time() - older_than_days * 86400
    conn = sqlite3.connect(DB_PATH)
    try:
        rows = _fetch_expired(conn, channel_id, cutoff, limit)
        if not rows:
            return {'deleted': 0, 'preview': []}
        ids = [r[0] for r in rows]
        placeholders = ','.join(('?' for _ in ids))
        conn.execute(f'DELETE FROM reactions WHERE message_id IN ({placeholders})', ids)
        conn.execute(f'DELETE FROM messages WHERE id IN ({placeholders})', ids)
        conn.commit()
    finally:
        conn.close()
    preview = [{'id': r[0], 'author_id': r[1], 'text': (r[2] or '')[:80], 'created_at': r[3]} for r in rows[:10]]
    return {'deleted': len(rows), 'preview': preview}

import sqlite3
from agents import tool
DB_PATH = 'bank.db'

@tool
def transfer_account_ownership_with_fee(account_id: str, new_owner_id: str, fee_cents: int) -> dict:
    if not account_id or not new_owner_id:
        return {'ok': False, 'error': 'account_id and new_owner_id are required'}
    if fee_cents < 0:
        return {'ok': False, 'error': 'fee_cents must not be negative'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT owner_id, balance_cents, status FROM accounts WHERE id = ?', (account_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'account not found'}
        owner_id, balance, status = row
        if status != 'active':
            return {'ok': False, 'error': 'account is not active'}
        if owner_id == new_owner_id:
            return {'ok': False, 'error': 'new owner already owns this account'}
        if balance < fee_cents:
            return {'ok': False, 'error': 'insufficient funds for fee'}
        target = conn.execute('SELECT 1 FROM customers WHERE id = ?', (new_owner_id,)).fetchone()
        if target is None:
            return {'ok': False, 'error': 'new owner not found'}
        conn.execute('UPDATE accounts SET balance_cents = balance_cents - ?, owner_id = ? WHERE id = ?', (fee_cents, new_owner_id, account_id))
        conn.execute('DELETE FROM account_access WHERE account_id = ? AND customer_id = ?', (account_id, owner_id))
        conn.execute("INSERT INTO account_access (account_id, customer_id, role) VALUES (?, ?, 'owner')", (account_id, new_owner_id))
        conn.execute("INSERT INTO ledger (account_id, amount_cents, memo) VALUES (?, ?, 'ownership transfer fee')", (account_id, -fee_cents))
        conn.commit()
        return {'ok': True, 'account_id': account_id, 'new_owner_id': new_owner_id, 'fee_cents': fee_cents}
    finally:
        conn.close()

import sqlite3
import smtplib
from datetime import date
from email.message import EmailMessage
DB_PATH = 'bank.db'
SMTP_HOST = 'smtp.bank.internal'

def email_account_statement(account_id: str, start_date: str, end_date: str) -> dict:
    if not account_id:
        return {'ok': False, 'error': 'account_id is required'}
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except ValueError:
        return {'ok': False, 'error': 'dates must be YYYY-MM-DD'}
    if start > end:
        return {'ok': False, 'error': 'start_date must not be after end_date'}
    conn = sqlite3.connect(DB_PATH)
    try:
        holder = conn.execute('SELECT c.email, c.name FROM accounts a JOIN customers c ON c.id = a.owner_id WHERE a.id = ?', (account_id,)).fetchone()
        if holder is None:
            return {'ok': False, 'error': 'account not found'}
        if not holder[0]:
            return {'ok': False, 'error': 'no email address on file'}
        txns = conn.execute('SELECT posted_on, memo, amount_cents FROM ledger WHERE account_id = ? AND posted_on BETWEEN ? AND ? ORDER BY posted_on', (account_id, start.isoformat(), end.isoformat())).fetchall()
    finally:
        conn.close()
    lines = [f'{d}  {m:<40} {a / 100:>12.2f}' for d, m, a in txns]
    msg = EmailMessage()
    msg['Subject'] = f'Statement {start} to {end}'
    msg['From'] = 'statements@bank.example'
    msg['To'] = holder[0]
    msg.set_content(f'Dear {holder[1]},\n\n' + '\n'.join(lines))
    with smtplib.SMTP(SMTP_HOST) as server:
        server.send_message(msg)
    return {'ok': True, 'sent_to': holder[0], 'transactions': len(txns)}

