import uuid
from agents import function_tool
DB_PATH = 'bank.db'

def _move_pending_record(conn, pending_id):
    conn.execute('INSERT INTO settled_transactions SELECT * FROM pending_transactions WHERE id = ?', (pending_id,))
    conn.execute('DELETE FROM pending_transactions WHERE id = ?', (pending_id,))

@function_tool
def move_funds_to_savings_vault(checking_id: str, savings_id: str, amount_cents: int) -> dict:
    if amount_cents <= 0:
        return {'ok': False, 'error': 'amount must be positive'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT balance_cents FROM accounts WHERE id = ?', (checking_id,)).fetchone()
        if row is None or row[0] < amount_cents:
            return {'ok': False, 'error': 'missing account or insufficient funds'}
        pending_id = str(uuid.uuid4())
        conn.execute('INSERT INTO pending_transactions (id, from_account, to_account, amount_cents) VALUES (?, ?, ?, ?)', (pending_id, checking_id, savings_id, amount_cents))
        conn.execute('UPDATE accounts SET balance_cents = balance_cents - ? WHERE id = ?', (amount_cents, checking_id))
        conn.execute('UPDATE accounts SET balance_cents = balance_cents + ? WHERE id = ?', (amount_cents, savings_id))
        _move_pending_record(conn, pending_id)
        conn.commit()
        return {'ok': True, 'transaction_id': pending_id, 'amount_cents': amount_cents}
    finally:
        conn.close()

import os
from dataclasses import dataclass
import gitlab
from langchain_core.tools import tool
_gl = gitlab.Gitlab(os.environ['GITLAB_URL'], private_token=os.environ['GITLAB_TOKEN'])

@dataclass
class GrantResult:
    project_id: int
    user_id: int
    access_level: int
    pipeline_id: int
    status: str

@tool
def grant_deploy_role_and_run_pipeline(project_id: int, user_id: int, ref: str) -> GrantResult:
    project = _gl.projects.get(project_id)
    try:
        member = project.members.get(user_id)
        member.access_level = gitlab.const.AccessLevel.DEVELOPER
        member.save()
    except gitlab.exceptions.GitlabGetError:
        member = project.members.create({'user_id': user_id, 'access_level': gitlab.const.AccessLevel.DEVELOPER})
    pipeline = project.pipelines.create({'ref': ref})
    return GrantResult(project_id=project_id, user_id=user_id, access_level=int(member.access_level), pipeline_id=pipeline.id, status=pipeline.status)

import time
from contextlib import contextmanager
from pathlib import Path
import boto3

@contextmanager
def _s3_session():
    client = boto3.client('s3')
    try:
        yield client
    finally:
        client.close()

def _old_files(root, cutoff):
    for path in root.rglob('*'):
        if path.is_file() and path.stat().st_mtime < cutoff:
            yield path

def purge_and_archive_build_artifacts(artifacts_dir: str, bucket: str, older_than_days: int) -> dict:
    root = Path(artifacts_dir)
    if not root.is_dir():
        return {'error': f'{artifacts_dir} is not a directory'}
    if older_than_days < 1:
        return {'error': 'older_than_days must be at least 1'}
    cutoff = time.time() - older_than_days * 86400
    archived = 0
    failed = []
    freed = 0
    with _s3_session() as s3:
        for path in _old_files(root, cutoff):
            key = 'artifacts/' + path.relative_to(root).as_posix()
            size = path.stat().st_size
            try:
                s3.upload_file(str(path), bucket, key)
            except Exception as exc:
                failed.append({'file': str(path), 'error': str(exc)})
                continue
            path.unlink()
            archived += 1
            freed += size
    return {'archived_and_removed': archived, 'bytes_freed': freed, 'failed': failed}

