import os
import requests
from agents import function_tool
_API = os.environ['CI_API_URL']
_HEADERS = {'Authorization': 'Bearer ' + os.environ['CI_API_TOKEN']}

@function_tool
def launch_paid_runner_deploy(project_id: int, hours: int, job_name: str) -> str:
    if project_id <= 0:
        return 'error: invalid project_id'
    if not 1 <= hours <= 24:
        return 'error: hours must be between 1 and 24'
    if not job_name.strip():
        return 'error: job_name is required'
    r = requests.post(f'{_API}/projects/{project_id}/runners/paid', json={'hours': hours}, headers=_HEADERS, timeout=30)
    r.raise_for_status()
    runner = r.json()
    requests.post(f"{_API}/runners/{runner['id']}/tokens", headers=_HEADERS, timeout=30).raise_for_status()
    j = requests.post(f'{_API}/projects/{project_id}/jobs/{job_name}/play', json={'runner_id': runner['id']}, headers=_HEADERS, timeout=30)
    j.raise_for_status()
    return f"runner {runner['id']} started job {j.json()['id']}"

import os
import requests
from langchain_core.tools import tool
ADS_API = 'https://ads.example.com/v1'
HEADERS = {'Authorization': f"Bearer {os.environ['ADS_API_TOKEN']}"}

def _get_engagement(post_id: str) -> dict:
    resp = requests.get(f'{ADS_API}/posts/{post_id}/metrics', headers=HEADERS, timeout=15)
    resp.raise_for_status()
    return resp.json()

@tool
def run_boosted_post_campaign(post_id: str, daily_budget_cents: int, days: int) -> dict:
    before = _get_engagement(post_id)
    payload = {'post_id': post_id, 'daily_budget_cents': daily_budget_cents, 'duration_days': days, 'billing': 'charge_now'}
    resp = requests.post(f'{ADS_API}/campaigns', json=payload, headers=HEADERS, timeout=30)
    resp.raise_for_status()
    campaign = resp.json()
    return {'campaign': campaign, 'engagement_before': before, 'total_cents': daily_budget_cents * days}

