import sqlite3
from dataclasses import dataclass
from agents import function_tool

@dataclass
class PurgeResult:
    applicant_id: int
    purged: bool
    applications_removed: int
    message: str

@function_tool
def purge_withdrawn_applicant(applicant_id: int, db_path: str='recruiting.db') -> PurgeResult:
    conn = sqlite3.connect(db_path)
    try:
        row = conn.execute('SELECT status, job_id FROM applicants WHERE id = ?', (applicant_id,)).fetchone()
        if row is None:
            return PurgeResult(applicant_id, False, 0, 'Applicant not found')
        status, job_id = row
        if status != 'withdrawn':
            return PurgeResult(applicant_id, False, 0, f"Applicant status is '{status}', not withdrawn")
        cur = conn.execute('DELETE FROM applications WHERE applicant_id = ?', (applicant_id,))
        removed = cur.rowcount
        conn.execute('DELETE FROM applicants WHERE id = ?', (applicant_id,))
        conn.execute('UPDATE job_postings SET applicant_count = MAX(applicant_count - 1, 0) WHERE id = ?', (job_id,))
        conn.commit()
        return PurgeResult(applicant_id, True, removed, 'Applicant purged')
    finally:
        conn.close()

import sqlite3
import stripe
DB_PATH = 'library.db'
PRICES_CENTS = {'4x6': 25, '5x7': 60, '8x10': 150, '16x20': 1200}

def order_photo_print(photo_id: int, size: str, quantity: int, stripe_customer_id: str) -> dict:
    if size not in PRICES_CENTS:
        return {'ok': False, 'error': f'unsupported size {size}'}
    if quantity < 1 or quantity > 50:
        return {'ok': False, 'error': 'quantity must be between 1 and 50'}
    if not stripe_customer_id.startswith('cus_'):
        return {'ok': False, 'error': 'invalid customer id'}
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute('SELECT file_name FROM photos WHERE id = ?', (photo_id,)).fetchone()
    conn.close()
    if row is None:
        return {'ok': False, 'error': 'photo not found'}
    intent = stripe.PaymentIntent.create(amount=PRICES_CENTS[size] * quantity, currency='usd', customer=stripe_customer_id, confirm=True, off_session=True, description=f'{quantity} x {size} print of {row[0]}')
    return {'ok': True, 'payment_id': intent.id, 'status': intent.status, 'file_name': row[0]}

import sqlite3
import subprocess
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('photo-library')
DB_PATH = 'library.db'
ALBUM_ROOT = Path('/srv/library/albums')

@mcp.tool()
def scan_album_and_add_editor(album_id: int, user_id: int) -> dict:
    album_dir = ALBUM_ROOT / str(album_id)
    result = subprocess.run(['clamscan', '--recursive', '--infected', str(album_dir)], capture_output=True, text=True, timeout=600)
    if result.returncode != 0:
        return {'granted': False, 'returncode': result.returncode, 'output': result.stdout[-2000:]}
    with sqlite3.connect(DB_PATH) as conn:
        conn.execute("INSERT INTO album_members (album_id, user_id, role) VALUES (?, ?, 'editor') ON CONFLICT(album_id, user_id) DO UPDATE SET role = 'editor'", (album_id, user_id))
    return {'granted': True, 'album_id': album_id, 'user_id': user_id, 'role': 'editor'}

