import sqlite3
from contextlib import closing
from datetime import datetime, timezone
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('photo-library')
DB_PATH = 'library.db'
ALLOWED_ROLES = ('editor', 'viewer')

def _demote_owner(conn: sqlite3.Connection, album_id: int, role: str) -> int:
    cur = conn.execute("UPDATE album_members SET role = ? WHERE album_id = ? AND role = 'owner'", (role, album_id))
    return cur.rowcount

def _promote_user(conn: sqlite3.Connection, album_id: int, user_id: int) -> None:
    conn.execute("INSERT INTO album_members (album_id, user_id, role) VALUES (?, ?, 'owner') ON CONFLICT(album_id, user_id) DO UPDATE SET role = 'owner'", (album_id, user_id))

def _log_transfer(conn: sqlite3.Connection, album_id: int, user_id: int, reason: str) -> None:
    conn.execute("INSERT INTO album_activity (album_id, action, user_id, note, created_at) VALUES (?, 'ownership_transferred', ?, ?, ?)", (album_id, user_id, reason, datetime.now(timezone.utc).isoformat()))

@mcp.tool()
def transfer_album_ownership(album_id: int, new_owner_id: int, previous_owner_role: str='editor', reason: str='') -> dict:
    if previous_owner_role not in ALLOWED_ROLES:
        return {'ok': False, 'error': 'previous_owner_role must be editor or viewer'}
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            demoted = _demote_owner(conn, album_id, previous_owner_role)
            if demoted == 0:
                return {'ok': False, 'error': 'album not found or has no owner'}
            _promote_user(conn, album_id, new_owner_id)
            conn.execute('UPDATE albums SET owner_id = ? WHERE id = ?', (new_owner_id, album_id))
            _log_transfer(conn, album_id, new_owner_id, reason)
    return {'ok': True, 'album_id': album_id, 'new_owner_id': new_owner_id, 'previous_owner_role': previous_owner_role}

import subprocess
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('k8s-ops')

@mcp.tool()
def apply_manifest_and_report_to_webhook(manifest_path: str, namespace: str, webhook_url: str, dry_run: bool=False) -> dict:
    kubectl_command_arguments = ['kubectl', 'apply', '-f', manifest_path, '-n', namespace]
    if dry_run:
        kubectl_command_arguments.append('--dry-run=server')
    completed_kubectl_process = subprocess.run(kubectl_command_arguments, capture_output=True, text=True, timeout=180)
    kubectl_exit_code = completed_kubectl_process.returncode
    kubectl_standard_output_text = completed_kubectl_process.stdout.strip()
    kubectl_standard_error_text = completed_kubectl_process.stderr.strip()
    webhook_payload_to_send = {'namespace': namespace, 'manifest': manifest_path, 'dry_run': dry_run, 'success': kubectl_exit_code == 0, 'output': kubectl_standard_output_text, 'errors': kubectl_standard_error_text}
    webhook_http_response = requests.post(webhook_url, json=webhook_payload_to_send, timeout=15)
    return {'exit_code': kubectl_exit_code, 'output': kubectl_standard_output_text, 'errors': kubectl_standard_error_text, 'webhook_status': webhook_http_response.status_code}

import shutil
import time
from pathlib import Path
from agents import function_tool

@function_tool
def archive_and_remove_old_files(source_directory: str, archive_directory: str, minimum_age_in_days: int) -> str:
    source_directory_path = Path(source_directory)
    archive_directory_path = Path(archive_directory)
    archive_directory_path.mkdir(parents=True, exist_ok=True)
    cutoff_timestamp_in_seconds = time.time() - minimum_age_in_days * 86400
    number_of_files_moved = 0
    for each_candidate_file_path in source_directory_path.rglob('*'):
        if each_candidate_file_path.is_file() and each_candidate_file_path.stat().st_mtime < cutoff_timestamp_in_seconds:
            destination_file_path = archive_directory_path / each_candidate_file_path.name
            shutil.move(str(each_candidate_file_path), str(destination_file_path))
            number_of_files_moved += 1
    number_of_empty_folders_deleted = 0
    for each_subfolder_path in sorted(source_directory_path.rglob('*'), reverse=True):
        if each_subfolder_path.is_dir() and (not any(each_subfolder_path.iterdir())):
            each_subfolder_path.rmdir()
            number_of_empty_folders_deleted += 1
    return 'Moved %d files and deleted %d empty folders' % (number_of_files_moved, number_of_empty_folders_deleted)
